def format_summarize(result: StrategicAnalysisResult) -> str:
    """Format the output of ``summarizeProject`` for terminal display."""
    lines = [
        _DIVIDER,
        "  ABM › summarize",
        f"  Project: {result.query}",
        _DIVIDER,
        f"\n  {len(result.context_items)} memory item(s) retrieved across all streams.",
        f"  {len(result.options)} strategic option path(s) identified:\n",
    ]

    for i, opt in enumerate(result.options, 1):
        streams_str = ", ".join(opt.supporting_streams) if opt.supporting_streams else "—"
        lines.append(f"  [{i}] {opt.title}")
        lines.append(f"      Streams  : {streams_str}")
        lines.append(f"      Rationale: {_snippet(opt.rationale, 200)}")
        if opt.tradeoffs:
            lines.append("      Trade-offs:")
            for t in opt.tradeoffs:
                lines.append(f"        • {t}")
        if opt.next_questions:
            lines.append("      Next questions:")
            for q in opt.next_questions:
                lines.append(f"        ? {q}")
        lines.append("")

    lines.append(_DIVIDER)
    return "\n".join(lines)

/// Light-weight service that reads / writes the desktop sync URL.
///
/// All callers that need the active base URL should call [getBaseUrl].
/// [CrossNodeSyncRepository] is constructed with this value at boot and
/// rebuilt whenever the user saves a new address in [SyncSettingsScreen].
class SyncSettingsService {
  SyncSettingsService({SharedPreferences? prefs}) : _prefs = prefs;

  SharedPreferences? _prefs;

  /// Returns the currently persisted base URL, or [kDefaultSyncBaseUrl] if
  /// no value has been saved yet.
  Future<String> getBaseUrl() async {
    await _ensurePrefs();
    return _prefs!.getString(kSyncBaseUrlPrefKey) ?? kDefaultSyncBaseUrl;
  }

  /// Persists [url] so it survives app restarts.
  /// Does NOT validate the URL format — callers (e.g. [SyncSettingsScreen])
  /// are responsible for basic validation before calling this.
  Future<void> setBaseUrl(String url) async {
    await _ensurePrefs();
    await _prefs!.setString(kSyncBaseUrlPrefKey, url);
  }

  /// Clears any saved URL, reverting to [kDefaultSyncBaseUrl] on next read.
  Future<void> resetToDefault() async {
    await _ensurePrefs();
    await _prefs!.remove(kSyncBaseUrlPrefKey);
  }

  Future<void> _ensurePrefs() async {
    _prefs ??= await SharedPreferences.getInstance();
  }
}

class AbmMobileApp extends StatelessWidget {
  const AbmMobileApp({super.key, required this.syncRepository});

  final CrossNodeSyncRepository syncRepository;

  @override
  Widget build(BuildContext context) {
    return MultiBlocProvider(
      providers: [
        BlocProvider<ForegroundBloc>(
          create: (_) => ForegroundBloc(service: AbmForegroundService.instance),
        ),
        BlocProvider<TelemetryBloc>(
          create: (_) => TelemetryBloc(
            repository: syncRepository,
          ),
        ),
      ],
      child: MaterialApp(
        title: 'ABM 2.0 — Cognitive OS',
        debugShowCheckedModeBanner: false,
        theme: ThemeData(
          colorScheme: ColorScheme.fromSeed(
            seedColor: const Color(0xFF1A1F36),
            brightness: Brightness.dark,
          ),
          useMaterial3: true,
        ),
        home: const _AbmHome(),
      ),
    );
  }
}

